    constexpr std::size_t InsightPageSize=10;const std::size_t insightTotal=insights.size(),insightPageCount=(insightTotal+InsightPageSize-1)/InsightPageSize,insightPage=insightPageCount?std::min<std::uint64_t>(requestedInsightPage,insightPageCount-1):0,insightBegin=std::min(insightTotal,insightPage*InsightPageSize),insightEnd=std::min(insightTotal,insightBegin+InsightPageSize);std::vector<Insight> pagedInsights(insights.begin()+insightBegin,insights.begin()+insightEnd);insights.swap(pagedInsights);
